package com.example.editor.gamification.feedback;
import java.time.Instant;import java.util.Collections;import java.util.LinkedHashMap;import java.util.List;import java.util.Map;
public record UserFeedbackEnvelope(String schemaVersion,String id,String semanticScopeId,String actorId,UserFeedbackKind kind,UserFeedbackSeverity severity,String title,String message,String reason,String nextStep,long pointsDelta,String pointTypeId,long progressCurrent,long progressTarget,String achievementId,String challengeId,String rewardId,String levelId,String sourceEventId,String correlationId,Instant occurredAt,UserFeedbackPresentationPolicy presentation,List<UserFeedbackAction> actions,Map<String,String> metadata){public UserFeedbackEnvelope{schemaVersion=schemaVersion==null||schemaVersion.isBlank()?"1.0":schemaVersion.trim();id=text(id);semanticScopeId=text(semanticScopeId);actorId=actorId==null||actorId.isBlank()?"system":actorId.trim();kind=kind==null?UserFeedbackKind.POINTS_AWARDED:kind;severity=severity==null?UserFeedbackSeverity.INFO:severity;title=text(title);message=text(message);reason=text(reason);nextStep=text(nextStep);pointTypeId=text(pointTypeId);achievementId=text(achievementId);challengeId=text(challengeId);rewardId=text(rewardId);levelId=text(levelId);sourceEventId=text(sourceEventId);correlationId=text(correlationId);occurredAt=occurredAt==null?Instant.now():occurredAt;presentation=presentation==null?UserFeedbackPresentationPolicy.defaults():presentation;actions=actions==null?List.of():List.copyOf(actions);metadata=metadata==null||metadata.isEmpty()?Map.of():Collections.unmodifiableMap(new LinkedHashMap<>(metadata));}
/** Descripción: Normaliza los identificadores y textos opcionales del sobre de retroalimentación. Entradas: value: valor textual. Salida: texto no nulo y sin espacios exteriores. */ private static String text(String value){return value==null?"":value.trim();}}
